function loadLeaflet(callback) {
  if (window.L) {
    callback();
    return;
  }
  const css = document.createElement("link");
  css.rel = "stylesheet";
  css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
  css.integrity = "sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=";
  css.crossOrigin = "";
  document.head.appendChild(css);
  const script = document.createElement("script");
  script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
  script.integrity = "sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=";
  script.crossOrigin = "";
  script.onload = callback;
  document.body.appendChild(script);
}
let map;
let marker;
let leafletLoaded = false;
const COORD_EPSILON = 1e-6;

// ---------------------------------------------------------------- capas y apariencia

const ZOOM_MAX = 20; // la ortofoto de Medellín tiene imagen real hasta aquí
const TESELA_VACIA = "data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==";
const MAPAS_MED = "https://www.medellin.gov.co/servidormapas/rest/services/ServiciosCiudad/";
const PANEL_ROTULOS = "rotulos";
function construirCapas() {
  const callejero = window.L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: ZOOM_MAX,
    maxNativeZoom: 19,
    zIndex: 1,
    attribution: "Tiles &copy; Esri &mdash; Source: Esri, DeLorme, NAVTEQ"
  });
  const mundo = window.L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: ZOOM_MAX,
    maxNativeZoom: 19,
    zIndex: 1,
    attribution: "Imágenes &copy; Esri, Maxar, Earthstar Geographics"
  });
  const medellin = window.L.tileLayer(MAPAS_MED + "IMAGEN_WEBM_2021/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: ZOOM_MAX,
    maxNativeZoom: 19,
    errorTileUrl: TESELA_VACIA,
    zIndex: 2,
    attribution: "Ortofoto 2021 &copy; Alcaldía de Medellín"
  });
  const rotulos = window.L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: ZOOM_MAX,
    maxNativeZoom: 19,
    errorTileUrl: TESELA_VACIA,
    pane: PANEL_ROTULOS,
    attribution: "Rótulos &copy; Esri"
  });
  return {
    callejero: callejero,
    satelite: window.L.layerGroup([mundo, medellin]),
    hibrido: window.L.layerGroup([mundo, medellin, rotulos])
  };
}
function ponerControles(capas) {
  window.L.control.layers({
    "Callejero": capas.callejero,
    "Satélite": capas.satelite,
    "Híbrido": capas.hibrido
  }, {}, {
    position: "topright",
    collapsed: false
  }).addTo(map);
  window.L.control.scale({
    position: "bottomleft",
    imperial: false
  }).addTo(map);
}

// ---------------------------------------------------------------- ciclo de vida

function initMap() {
  if (!window.L) return;
  leafletLoaded = true;
  const rawLat = parseFloat(appsmith.model.latitud);
  const rawLng = parseFloat(appsmith.model.longitud);
  if (map) {
    const current = marker.getLatLng();
    const lat = isNaN(rawLat) ? current.lat : rawLat;
    const lng = isNaN(rawLng) ? current.lng : rawLng;
    const changed = Math.abs(current.lat - lat) > COORD_EPSILON || Math.abs(current.lng - lng) > COORD_EPSILON;
    if (changed) {
      marker.setLatLng([lat, lng]);
      map.setView([lat, lng], map.getZoom());
    }
    return;
  }
  const lat = isNaN(rawLat) ? 6.2442 : rawLat;
  const lng = isNaN(rawLng) ? -75.5812 : rawLng;
  map = window.L.map("map").setView([lat, lng], 13);

  // Panel propio para los rótulos, por encima de las teselas (200) y bajo el marcador (600)
  map.createPane(PANEL_ROTULOS);
  map.getPane(PANEL_ROTULOS).style.zIndex = 650;
  map.getPane(PANEL_ROTULOS).style.pointerEvents = "none";
  const capas = construirCapas();
  capas.hibrido.addTo(map); // arranca en híbrido

  marker = window.L.marker([lat, lng], {
    draggable: true
  }).addTo(map);
  marker.on("dragend", function (e) {
    const pos = e.target.getLatLng();
    appsmith.updateModel({
      latitud: pos.lat.toFixed(6),
      longitud: pos.lng.toFixed(6)
    });
    appsmith.triggerEvent("onResetClick");
  });
  map.on("click", function (e) {
    marker.setLatLng(e.latlng);
    appsmith.updateModel({
      latitud: e.latlng.lat.toFixed(6),
      longitud: e.latlng.lng.toFixed(6)
    });
    appsmith.triggerEvent("onResetClick");
  });
  ponerControles(capas);
}
appsmith.onReady(() => {
  loadLeaflet(initMap);
});
appsmith.onModelChange(() => {
  if (leafletLoaded) {
    initMap();
  }
});

